                  '| `START` | 기사; 유효 확정 예약에서 실제 시작 |\n'
                  '| `REQUEST_STOP` | 사용자; 작업 중 사유 입력·점유 유지 |\n'
                  '| `STOP` | 기사; 사용자 요청 확인 또는 직접 중단·수행 기록 필수 |\n'
